#include "autogenerated.h"
#include "uart.h"
#include "tilt_control.h"

L298N driver1({
        GPIOA, GPIO_PIN_0,
        GPIOA, GPIO_PIN_1
    }, {
        GPIOA, GPIO_PIN_2,
        GPIOA, GPIO_PIN_3
    }
);

L298N driver2({
        GPIOA, GPIO_PIN_8,
        GPIOA, GPIO_PIN_11
    }, {
        GPIOB, GPIO_PIN_0,
        GPIOB, GPIO_PIN_1
    }
);

TiltController tilt_ctrl(driver1, driver2);

void setup() {
    hal_setup();
    tilt_ctrl.init();
    tilt_ctrl.lower_all();
}

int main() {
    setup();

    set_uart_mode(UART_MODE_BLOCKING);

    while (1) {
        uart_printf("testing\n");     
    }
}